import os
import pandas as pd
from pathlib import Path

# First, let's check what files are available in the current directory
print("Available files in current directory:")
for file in os.listdir('.'):
    if file.endswith(('.txt', '.pdf', '.docx', '.md', '.json', '.csv')):
        print(f"  - {file}")

# Let's also check for any policy-related files
print("\nLooking for policy-related files:")
policy_files = []
for file in os.listdir('.'):
    if 'policy' in file.lower() or 'terms' in file.lower() or 'agreement' in file.lower():
        policy_files.append(file)
        print(f"  - {file}")

if not policy_files:
    print("No policy files found. Let's check subdirectories...")
    for root, dirs, files in os.walk('.'):
        for file in files:
            if 'policy' in file.lower() or 'terms' in file.lower() or 'agreement' in file.lower():
                full_path = os.path.join(root, file)
                policy_files.append(full_path)
                print(f"  - {full_path}")

print(f"\nFound {len(policy_files)} policy-related files")

